"""Generate typed SQL projections and the TS field manifest from the v1 contract."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[2]; server=root/'server'
spec=json.loads((server/'contracts/entities.json').read_text())
(root/'packages/application/src/sync-entity-fields.ts').write_text('// Generated by server/tools/generate.py; do not edit.\nexport const syncEntityFields = '+json.dumps(spec,indent=2)+' as const;\n')
base='''-- +goose Up
CREATE TABLE users (id text PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), installation_id text NOT NULL, name text NOT NULL, revoked_at timestamptz, UNIQUE(user_id,installation_id), UNIQUE(user_id,id));
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL, device_id text NOT NULL, refresh_hash bytea NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, FOREIGN KEY(user_id,device_id) REFERENCES devices(user_id,id));
CREATE TABLE sync_heads (user_id text PRIMARY KEY REFERENCES users(id), revision bigint NOT NULL DEFAULT 0);
CREATE TABLE sync_batches (user_id text NOT NULL REFERENCES users(id), batch_id text NOT NULL, device_id text NOT NULL, request_hash text NOT NULL, revision bigint NOT NULL, result jsonb NOT NULL, PRIMARY KEY(user_id,batch_id), UNIQUE(user_id,revision));
CREATE TABLE sync_changes (user_id text NOT NULL, revision bigint NOT NULL, batch_id text NOT NULL, document jsonb NOT NULL, PRIMARY KEY(user_id,revision), FOREIGN KEY(user_id,batch_id) REFERENCES sync_batches(user_id,batch_id));
CREATE TABLE sync_conflicts (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text NOT NULL, batch_id text NOT NULL, request_hash text NOT NULL, local_batch jsonb NOT NULL, remote_entities jsonb NOT NULL, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','cloud','local')), resolution jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,batch_id));
CREATE TABLE sync_bootstraps (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), device_id text NOT NULL, direction text NOT NULL CHECK(direction IN ('upload','download')), revision bigint NOT NULL, status text NOT NULL DEFAULT 'staging', chunks jsonb NOT NULL DEFAULT '{}', snapshot jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now());
'''
refs={'project':{'goalId':'goal'},'task':{'projectId':'project','goalId':'goal','parentTaskId':'task'},'time_block':{'taskId':'task'},'execution_session':{'taskId':'task','timeBlockId':'time_block'},'execution_interval':{'sessionId':'execution_session'},'completion_record':{'taskId':'task','sourceSessionId':'execution_session','operationId':'operation_provenance'},'achievement':{'sourceCompletionRecordId':'completion_record','sourceTaskId':'task','sourceExecutionSessionId':'execution_session'},'task_activity':{'taskId':'task','timeBlockId':'time_block','operationId':'operation_provenance'}}
query=''; unions=[];dispatch=''
for kind,e in spec.items():
 table='facts_'+kind;cols=[]
 for f,v in e['fields'].items():
  typ={'number':'double precision','boolean':'boolean','json':'jsonb'}.get(v['type'],'text')
  cols.append(f'"{f}" {typ}'+('' if v['nullable'] else ' NOT NULL'))
 base+=f'CREATE TABLE {table} (user_id text NOT NULL REFERENCES users(id), entity_key text NOT NULL, version bigint NOT NULL CHECK(version>0), owner_device_id text NOT NULL, '+', '.join(cols)+', PRIMARY KEY(user_id,entity_key), UNIQUE(user_id,id));\n'
 name=''.join(w.title() for w in kind.split('_'))
 names=list(e['fields']);quoted=', '.join('"'+f+'"' for f in names)
 select=', '.join('x."'+f+'"' for f in names)
 fields=', '.join('"'+f+'" '+{'number':'double precision','boolean':'boolean','json':'jsonb'}.get(v['type'],'text') for f,v in e['fields'].items())
 update=', '.join('"'+f+'"=EXCLUDED."'+f+'"' for f in names)
 query+=f'-- name: Put{name} :exec\nINSERT INTO {table} (user_id,entity_key,version,owner_device_id,{quoted}) SELECT sqlc.arg(user_id)::text,sqlc.arg(entity_key)::text,sqlc.arg(version)::bigint,sqlc.arg(owner_device_id)::text,{select} FROM jsonb_to_record(sqlc.arg(document)::jsonb) AS x({fields}) ON CONFLICT(user_id,entity_key) DO UPDATE SET version=EXCLUDED.version, {update};\n\n'
 unions.append(f"SELECT user_id, '{kind}'::text AS kind, entity_key, version, owner_device_id, to_jsonb(f)-'user_id'-'entity_key'-'version'-'owner_device_id' AS document FROM {table} f")
for kind,fields in refs.items():
 for field,target in fields.items():
  base+=f'ALTER TABLE facts_{kind} ADD FOREIGN KEY(user_id,"{field}") REFERENCES facts_{target}(user_id,id) DEFERRABLE INITIALLY DEFERRED;\n'
base+='''CREATE UNIQUE INDEX facts_completion_task_unique ON facts_completion_record(user_id,"taskId");
CREATE UNIQUE INDEX facts_achievement_completion_unique ON facts_achievement(user_id,"sourceCompletionRecordId");
CREATE UNIQUE INDEX facts_session_active_unique ON facts_execution_session(user_id) WHERE status IN ('running','paused');
CREATE UNIQUE INDEX facts_relax_active_unique ON facts_relax_session(user_id) WHERE status='active';
CREATE UNIQUE INDEX facts_preference_key_unique ON facts_preference(user_id,"key");
CREATE UNIQUE INDEX facts_reflection_day_unique ON facts_reflection(user_id,"localDate","timeZone");
'''
base+='CREATE VIEW sync_entities AS '+'\nUNION ALL\n'.join(unions)+';\n'
base+='-- +goose Down\nDROP VIEW sync_entities;\n'
base+='DROP TABLE '+', '.join('facts_'+k for k in reversed(spec))+', sync_bootstraps, sync_conflicts, sync_changes, sync_batches, sync_heads, sessions, devices, users CASCADE;\n'
initial=server/'db/migrations/00001_accounts_sync.sql'
if 'plan_origin' in spec and initial.exists():
 import re
 old=initial.read_text()
 table=re.search(r'CREATE TABLE facts_plan_origin .*?;\n',base).group(0)
 newview=re.search(r'CREATE VIEW sync_entities AS .*?;\n',base,re.S).group(0).replace('CREATE VIEW','CREATE OR REPLACE VIEW',1)
 oldview=re.search(r'CREATE VIEW sync_entities AS .*?;\n',old,re.S).group(0).replace('CREATE VIEW','CREATE OR REPLACE VIEW',1)
 (server/'db/migrations/00002_plan_origins.sql').write_text('-- +goose Up\n'+table+newview+'-- +goose Down\n'+oldview+'DROP TABLE facts_plan_origin;\n')
else: initial.write_text(base)
query+='''-- name: ListEntities :many
SELECT kind,entity_key,version,owner_device_id,document::jsonb AS document FROM sync_entities WHERE user_id=$1 ORDER BY kind,entity_key;

-- name: GetEntity :one
SELECT kind,entity_key,version,owner_device_id,document::jsonb AS document FROM sync_entities WHERE user_id=$1 AND kind=$2 AND entity_key=$3;
'''
(server/'db/queries/facts.sql').write_text(query)
# Dispatch is generated because only named, sqlc-checked queries may touch fact tables.
code='// Code generated by tools/generate.py. DO NOT EDIT.\npackage data\nimport ("context"; "encoding/json"; "personal-execution/server/internal/data/sqlcdb")\nfunc putFact(ctx context.Context,q *sqlcdb.Queries,user,kind,key,owner string,version int64,doc json.RawMessage) error {\nswitch kind {\n'
for kind in spec:
 name=''.join(w.title() for w in kind.split('_'))
 code+=f'case "{kind}": return q.Put{name}(ctx,sqlcdb.Put{name}Params{{UserID:user,EntityKey:key,Version:version,OwnerDeviceID:owner,Document:doc}})\n'
code+='};return ErrInvalid\n}\n'
(server/'internal/data/facts_generated.go').write_text(code)
